    "stem": "Lactente de 9 meses foi admitido em Unidade de Pronto Atendimento (UPA) com quadro de diarreia; febre de 38,5 °C; diminuição do volume urinário; sonolência alternada com períodos de irritabilidade; apatia; palidez de pele. Ao exame físico: peso de 9 kg; temperatura axilar de 38 °C; frequência cardíaca e 130 bpm; frequência respiratória de 34 rpm; pressão arterial de 80 x 50 mmHg; mau estado geral; sonolento; reagindo com irritabilidade aos estímulos; palidez de pele; tecido subcutâneo com turgor pastoso; mucosas ressecadas; olhos encovados; extremidades frias; pulsos fracos. Tempo de enchimento capilar de 4 segundos. Respiração gemente, com aumento da amplitude e tiragens intercostais. O diagnóstico e a hidratação endovenosa indicada para o caso são, respectivamente,",
