    "id": "revalida-2024-1-005",
    "number": 5,
    "stem": "Ao assumir a coordenação de uma equipe de saúde da família, um médico de família e comunidade percebe que sua equipe não utiliza critérios para estabelecimento de fluxo de agendamento de visitas domiciliares. Diante dessa situação, ele decide promover uma roda de conversa a fim de sensibilizar sua equipe acerca da necessidade de organizar critérios para a definição das visitas domiciliares como uma abordagem ao indivíduo em seu aspecto familiar e comunitário.",
