    "number": 99,
    "stem": "Uma paciente com 45 anos, nuligesta, com ciclos menstruais irregulares, é encaminhada da atenção básica para ambulatório especializado de Ginecologia. Ela apresenta ultrassonografia transvaginal que evidencia cisto de 6 cm, com projeção papilar no seu interior, no ovário esquerdo, e que se mostram normais o ovário direito e demais estruturas pélvicas.\n\nConsiderando-se esse caso, o critério que determinará a investigação cirúrgica será",
