    "examId": "revalida-2026-1",
    "examName": "Revalida INEP: 2026.1",
    "stem": "Síndrome Inflamatória Multissistêmica Menina, 8 anos, previamente hígida, é levada à Unidade de Pronto Atendimento com quadro de febre (39 a 40 °C) há 5 dias, associado à dor abdominal intensa, vômitos, exantema maculopapular em tronco e hiperemia conjuntival bilateral sem secreção. A mãe refere que a criança teve um quadro gripal leve há cerca de 4 semanas com teste de covid-19 positivo. Exame físico: prostrada; tempo de enchimento capilar de 4 segundos; pulsos Enos; FC 135 bpm; PA 75 x 45 mmHg (abaixo do percentil 5 para idade e estatura); SatO2 91% em ar ambiente. Ausculta cardíaca revela ritmo de galope. Palpação abdominal mostra descompressão brusca negativa, mas com dor importante à palpação profunda. Qual é a principal suspeita clínica?",
