    "examName": "Revalida INEP: 2026.1",
    "stem": "BIRADS 4 Mulher, 51 anos, comparece à consulta ginecológica na Unidade Básica de Saúde para apresentar mamografia realizada há 1 mês. Não apresenta queixas relacionadas à mama e não possui alterações no exame físico. Nega comorbidades e histórico familiar de doenças mamárias ou oncológicas. Mamografia bilateral. Mama esquerda: parênquima fibroglandular denso. Presença de calcificações pleomórficas finas, com distribuição segmentar, no quadrante ínferomedial. Mama direita: parênquima Ebroglandular denso. Ausência de achados significativos. Mamografia BI-RADS 4C. Considerando os achados mamográficos, qual é a conduta recomendada?",
    "options": {
      "A": "Solicitar avaliação complementar com ressonância magnética.",
      "B": "Manter seguimento conforme a rotina habitual de rastreamento.",
      "C": "Repetir a mamografia bilateral em 6 meses para controle evolutivo.",
      "D": "Encaminhar a paciente para serviço especializado em mastologia."
    },
    "answer": "D",
    "explanation": "",
    "needsVisualReview": false,
