    "stem": "Uma mãe leva ao pronto-socorro sua filha de 3 anos, com quadro de gastroenterite. Durante seu relato informa que a criança vinha apresentando febre persistente e que, por isso, administrou dose elevada de antitérmico. Diante desse quadro, a médica prescreve N-acetilcisteína como antídoto para a intoxicação.\n\nConsiderando a prescrição médica, assinale a alternativa que apresenta o medicamento que causou a intoxicação.",
