    "id": "revalida-2024-1-002",
    "number": 2,
    "stem": "Um paciente com 28 anos, vítima de atropelamento, é levado ao departamento de emergência pelo Serviço de atendimento médico de urgência (SAMU). Ao exame abdominal, apresenta escoriações e hematoma em baixo ventre, instabilidade à palpação da pelve e hematoma perineal. Após avaliação primária, qual das seguintes alternativas corresponde ao melhor método diagnóstico de possível lesão do trato urinário, no caso apresentado?",
