    "id": "revalida-2023-2-008",
    "number": 8,
    "stem": "Um adolescente de 18 anos encontra-se internado após cirurgia bariátrica (derivação gástrica em Y-de-Roux) realizada há 3 meses. Ele refere que, ocasionalmente, apresenta náuseas, diarreia, dor abdominal, sudorese, sensação de desmaio iminente e fraqueza cerca de 2 a 3 horas após a ingestão de carboidratos simples, os quais consome com frequência. Seu exame físico apresenta-se sem alterações no momento. Exames de bioquímica, de imagem e endoscopia digestiva alta também apresentam-se sem alterações.\nDiante desse quadro, qual é a hipótese diagnóstica mais provável?",
    "options": {
      "A": "Fístula gastro-gástrica.",
      "B": "Síndrome de dumping.",
      "C": "Peritonite bacteriana secundária.",
      "D": "Deficiência de ferro e de vitaminas do complexo B."
    },
    "answer": "B",
    "area": "Clínica Médica",
