    "number": 47,
    "stem": "Uma paciente de 40 anos, cosmetologista, is trazida ao pronto-socorro com relato de exposição acidental de olho esquerdo a ácido tricloroacético durante a realização de procedimento dermatológico ambulatorial, há 1 hora.\n\nA conduta terapêutica inicial adequada para essa paciente é realizar",
