    "id": "revalida-2023-2-048",
    "number": 48,
    "stem": "Um menino de 9 anos, sem comorbidades, é levado pela mãe à consulta ambulatorial por apresentar baixa estatura. A mãe refere que seu filho é o mais baixo entre os colegas da sala de aula. Na avaliação antropométrica, evidencia-se que o paciente apresenta mais de 3 desvios-padrão (escore Z: -3) da curva de altura/idade e escore Z=0 para peso/altura da Organização Mundial de Saúde. Demais aspectos do exame físico sem alterações. Foram realizados dois testes provocativos da secreção de hormônio de crescimento (GH), com resultados de 4,2 e 4,3 mcg/dL respectivamente (Valor de referência de GH > 5mcg/L).\n\nCom base nesse achado, o diagnóstico etiológico mais provável da baixa estatura, é",
