    "id": "revalida-2023-2-049",
    "number": 49,
    "stem": "Uma mulher de 35 anos procura unidade básica de saúde para fazer exame de rastreio de câncer de mama. Ela informa que sua mãe foi diagnosticada com câncer de ovário aos 72 anos e que seu pai faleceu de câncer de intestino. A paciente é nulípara, faz uso de anticoncepcional oral desde a adolescência, é obesa e tabagista há 10 anos fazendo uso de 10 cigarros por dia.\n\nNesse caso, a conduta adequada é",
