    "stem": "Um recém-nascido de 2 dias de vida, a termo, sem pré-natal adequado e que está em alojamento conjunto, vem apresentando icterícia e hepatomegalia. Na investigação, foi realizado o diagnóstico de toxoplasmose congênita.\nComo uma complicação dessa doença, a criança poderá apresentar",
