    "id": "revalida-2023-1-092",
    "number": 92,
    "stem": "Em visita domiciliar da estratégia de saúde da família, é atendido um homem com 53 anos, ex-tabagista (consumo de 20 cigarros/dia) que parou de fumar há 15 anos. Ele relata que foi submetido a colonoscopia há 3 meses, em razão de diarreia prolongada, quando se evidenciou uma lesão polipoide com 0,5 cm no reto, tendo sido realizada polipectomia, cujo laudo anatomopatológico revelou um pólipo hiperplásico. Afirma não haver história de câncer colorretal na família.\n\nA classificação de risco para câncer colorretal nesse paciente e a estratégia de acompanhamento, visando o rastreamento desse tipo de neoplasia conforme as diretrizes brasileiras, são, respectivamente,",
